options.getOption:
const frame = context.panel.data.series[0];
const field = (name) => frame?.fields.find((item) => item.name === name);
if (!field('Pace')) {
  return {};
}

const theme = context.grafana.theme;
const text = theme.colors.text.secondary;
const color = (name) => theme.visualization.getColorByName(name);
const elapsed = Array.from(field('Elapsed').values);
const paces = Array.from(field('Pace').values);
const clock = (seconds) => {
  const total = Math.round(seconds);
  const hours = Math.floor(total / 3600);
  const minutes = String(Math.floor((total % 3600) / 60)).padStart(hours ? 2 : 1, '0');
  const rest = `${minutes}:${String(total % 60).padStart(2, '0')}`;
  return hours ? `${hours}:${rest}` : rest;
};

return {
  backgroundColor: 'transparent',
  tooltip: { formatter: (item) => `${clock(item.value[0])}<br/>${clock(item.value[1])} /mi` },
  grid: { left: 8, right: 16, top: 8, bottom: 8, containLabel: true },
  visualMap: {
    show: false,
    dimension: 1,
    pieces: [
      { lt: 1159, color: color('semi-dark-green') },
      { gte: 1159, lt: 1609, color: color('light-green') },
      { gte: 1609, color: color('#EAB839') },
    ],
  },
  xAxis: {
    type: 'value',
    min: 0,
    max: 'dataMax',
    axisLabel: { color: text, formatter: clock },
    splitLine: { show: false },
  },
  // Inverse puts faster paces on top. The query leaves out paces slower than 30:00 per mile.
  yAxis: {
    type: 'value',
    inverse: true,
    min: (range) => Math.floor(range.min / 60) * 60,
    max: (range) => Math.min(1800, Math.ceil(range.max / 60) * 60),
    axisLabel: { color: text, formatter: clock },
    splitLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  series: [{ type: 'scatter', symbolSize: 5, data: elapsed.map((value, index) => [value, paces[index]]) }],
};
